def items_in_category(cat: str) -> list:
    """Shop listing helpers with merged related items for accurate counts."""
    if cat == "defense":
        return [c for c in CATALOG if c.get("category") == "defense" or str(c.get("item_code", "")).startswith("m_sam")]
    if cat == "mine":
        # resources + uranium products players expect under mines
        return [
            c for c in CATALOG
            if c.get("category") == "mine"
            or str(c.get("item_code", "")).startswith("res_")
            or c.get("item_code") in ("res_uranium", "res_uranium_90")
        ]
    return [c for c in CATALOG if c.get("category") == cat]

def item_meta(code: str) -> dict | None:
    for c in CATALOG:
        if c["item_code"] == code:
            return c
    return None

